using System.Globalization;
using Npgsql;
using Todir.Modules.Catalog.Contracts;
using Todir.Modules.Catalog.Domain;
using Todir.Platform.Transactions;
using Todir.SharedKernel.Identifiers;

namespace Todir.Modules.Catalog.Application;

public sealed class CatalogDetailService(ITransactionCoordinator coordinator, NpgsqlDataSource dataSource)
{
    public async Task<VariantDto> CreateVariantAsync(TenantId tenantId, Guid templateId, CreateVariantRequest request, CancellationToken ct)
    {
        var variantId = Guid.CreateVersion7(); var sku = string.IsNullOrWhiteSpace(request.Sku) ? null : request.Sku.Trim(); var normalized = sku is null ? null : CatalogNormalization.Text(sku);
        await coordinator.ExecuteAsync(tenantId, async (context, token) => { var status = await ScalarAsync<string?>(context, "select status from foundation_catalog.product_template where tenant_id=$1 and id=$2", token, tenantId.Value, templateId); if (!string.Equals(status, "Active", StringComparison.Ordinal)) throw new CatalogException("catalog.product_not_active", "Variants can only be added to an active product."); await ExecuteAsync(context, "insert into foundation_catalog.product_variant (tenant_id,id,product_template_id,sku,normalized_sku,is_default_variant,status,created_at,updated_at,version) values ($1,$2,$3,$4,$5,false,'Active',$6,$6,1)", token, tenantId.Value, variantId, templateId, sku ?? (object)DBNull.Value, normalized ?? (object)DBNull.Value, DateTimeOffset.UtcNow); var baseUomId = await ScalarAsync<Guid>(context, "select uom_id from foundation_catalog.product_uom where tenant_id=$1 and variant_id=(select id from foundation_catalog.product_variant where tenant_id=$1 and product_template_id=$2 and is_default_variant) and is_base and status='Active' and effective_to is null", token, tenantId.Value, templateId); await ExecuteAsync(context, "insert into foundation_catalog.product_uom (tenant_id,id,variant_id,uom_id,factor_to_base,is_base,effective_from,status,version) values ($1,$2,$3,$4,1,true,$5,'Active',1)", token, tenantId.Value, Guid.CreateVersion7(), variantId, baseUomId, DateTimeOffset.UtcNow); await RefreshProjectionAsync(context, tenantId, templateId, variantId, token); return true; }, ct);
        return new VariantDto(variantId, templateId, sku, null, false, CatalogStatus.Active, 1);
    }

    public async Task<ProductUomDto> AddUomAsync(TenantId tenantId, Guid templateId, Guid variantId, AddProductUomRequest request, CancellationToken ct)
    {
        if (request.FactorToBase <= 0 || (request.EffectiveTo is not null && request.EffectiveTo <= request.EffectiveFrom)) throw new CatalogException("catalog.conversion_invalid", "Conversion factor and effective dates are invalid."); var id = Guid.CreateVersion7();
        return await coordinator.ExecuteAsync(tenantId, async (context, token) => { var variantTemplate = await ScalarNullableGuidAsync(context, "select product_template_id from foundation_catalog.product_variant where tenant_id=$1 and id=$2 and status='Active'", token, tenantId.Value, variantId); if (variantTemplate != templateId) throw new CatalogException("catalog.variant_not_found", "Variant was not found for this product."); var baseDimension = await ScalarAsync<string>(context, "select u.dimension from foundation_catalog.product_uom pu join foundation_catalog.uom u on u.tenant_id=pu.tenant_id and u.id=pu.uom_id where pu.tenant_id=$1 and pu.variant_id=$2 and pu.is_base and pu.status='Active' and pu.effective_to is null", token, tenantId.Value, variantId); var unitDimension = await ScalarAsync<string>(context, "select dimension from foundation_catalog.uom where tenant_id=$1 and id=$2 and status='Active'", token, tenantId.Value, request.UomId); if (!string.Equals(baseDimension, unitDimension, StringComparison.Ordinal) && baseDimension != "BusinessUnit" && unitDimension != "BusinessUnit") throw new CatalogException("catalog.uom_dimension_mismatch", "Units from different dimensions cannot be converted."); var overlap = await ScalarAsync<bool>(context, "select exists(select 1 from foundation_catalog.product_uom where tenant_id=$1 and variant_id=$2 and uom_id=$3 and status='Active' and not (coalesce(effective_to,'infinity'::timestamptz) <= $4 or coalesce($5,'infinity'::timestamptz) <= effective_from))", token, tenantId.Value, variantId, request.UomId, request.EffectiveFrom, request.EffectiveTo ?? (object)DBNull.Value); if (overlap) throw new CatalogException("catalog.conversion_overlap", "Effective conversion periods cannot overlap."); await ExecuteAsync(context, "insert into foundation_catalog.product_uom (tenant_id,id,variant_id,uom_id,factor_to_base,is_base,effective_from,effective_to,status,version) values ($1,$2,$3,$4,$5,false,$6,$7,'Active',1)", token, tenantId.Value, id, variantId, request.UomId, request.FactorToBase, request.EffectiveFrom, request.EffectiveTo ?? (object)DBNull.Value); var code = await ScalarAsync<string>(context, "select code from foundation_catalog.uom where tenant_id=$1 and id=$2", token, tenantId.Value, request.UomId); return new ProductUomDto(id, variantId, request.UomId, code, request.FactorToBase, false, request.EffectiveFrom, request.EffectiveTo, CatalogStatus.Active); }, ct);
    }

    public async Task<IReadOnlyList<ProductUomDto>> ListUomsAsync(TenantId tenantId, Guid variantId, CancellationToken ct)
    {
        await using var connection = await dataSource.OpenConnectionAsync(ct); await SetTenantAsync(connection, tenantId, ct); await using var command = new NpgsqlCommand("select pu.id,pu.variant_id,pu.uom_id,u.code,pu.factor_to_base,pu.is_base,pu.effective_from,pu.effective_to,pu.status from foundation_catalog.product_uom pu join foundation_catalog.uom u on u.tenant_id=pu.tenant_id and u.id=pu.uom_id where pu.tenant_id=$1 and pu.variant_id=$2 order by pu.is_base desc,pu.effective_from", connection); command.Parameters.AddWithValue(tenantId.Value); command.Parameters.AddWithValue(variantId); var result = new List<ProductUomDto>(); await using var reader = await command.ExecuteReaderAsync(ct); while (await reader.ReadAsync(ct)) result.Add(new ProductUomDto(reader.GetGuid(0),reader.GetGuid(1),reader.GetGuid(2),reader.GetString(3),reader.GetDecimal(4),reader.GetBoolean(5),reader.GetFieldValue<DateTimeOffset>(6),reader.IsDBNull(7)?null:reader.GetFieldValue<DateTimeOffset>(7),Enum.Parse<CatalogStatus>(reader.GetString(8)))); return result;
    }

    public async Task<ProductVariantSnapshot> ResolveAsync(TenantId tenantId, string value, CancellationToken ct)
    {
        var normalizedSku = CatalogNormalization.Text(value); var normalizedBarcode = IdentifierRules.RequireBarcode(value); await using var connection = await dataSource.OpenConnectionAsync(ct); await SetTenantAsync(connection, tenantId, ct); await using var command = new NpgsqlCommand("select v.id,p.id,v.sku,p.display_name,base.uom_id,base.factor_to_base from foundation_catalog.product_variant v join foundation_catalog.product_template p on p.tenant_id=v.tenant_id and p.id=v.product_template_id left join foundation_catalog.product_uom base on base.tenant_id=v.tenant_id and base.variant_id=v.id and base.is_base and base.status='Active' and base.effective_to is null where v.tenant_id=$1 and v.status='Active' and p.status='Active' and (v.normalized_sku=$2 or exists(select 1 from foundation_catalog.product_barcode b where b.tenant_id=v.tenant_id and b.variant_id=v.id and b.normalized_value=$3 and b.status='Active')) limit 1", connection); command.Parameters.AddWithValue(tenantId.Value); command.Parameters.AddWithValue(normalizedSku); command.Parameters.AddWithValue(normalizedBarcode); await using var reader = await command.ExecuteReaderAsync(ct); if (!await reader.ReadAsync(ct)) throw new CatalogException("catalog.identifier_not_found", "No active product matches this SKU or barcode."); return new ProductVariantSnapshot(reader.GetGuid(0),reader.GetGuid(1),reader.IsDBNull(2)?null:reader.GetString(2),reader.GetString(3),reader.GetGuid(4),reader.GetDecimal(5));
    }

    public async Task<ProductReadinessDto> ReadinessAsync(TenantId tenantId, Guid templateId, CancellationToken ct)
    {
        await using var connection = await dataSource.OpenConnectionAsync(ct); await SetTenantAsync(connection, tenantId, ct); await using var command = new NpgsqlCommand("select p.id,p.display_name,p.product_nature,exists(select 1 from foundation_catalog.product_variant v join foundation_catalog.product_uom pu on pu.tenant_id=v.tenant_id and pu.variant_id=v.id and pu.is_base and pu.status='Active' and pu.effective_to is null where v.tenant_id=p.tenant_id and v.product_template_id=p.id) as has_base,exists(select 1 from foundation_catalog.product_variant v join foundation_catalog.product_barcode b on b.tenant_id=v.tenant_id and b.variant_id=v.id and b.status='Active' where v.tenant_id=p.tenant_id and v.product_template_id=p.id) as has_barcode from foundation_catalog.product_template p where p.tenant_id=$1 and p.id=$2", connection); command.Parameters.AddWithValue(tenantId.Value); command.Parameters.AddWithValue(templateId); await using var reader = await command.ExecuteReaderAsync(ct); if (!await reader.ReadAsync(ct)) throw new CatalogException("catalog.product_not_found", "Product was not found."); var missing = new List<string>(); var warnings = new List<string>(); if (!reader.GetBoolean(3)) missing.Add("base_uom"); if (reader.GetString(2) == "Goods" && !reader.GetBoolean(4)) warnings.Add("goods_without_barcode"); return new ProductReadinessDto(templateId, missing.Count == 0, missing, warnings);
    }

    public async Task<bool> AddAliasAsync(TenantId tenantId, Guid templateId, AddAliasRequest request, CancellationToken ct) { return await coordinator.ExecuteAsync(tenantId, async (context, token) => { await EnsureVariantAsync(context, tenantId, templateId, request.VariantId, token); await ExecuteAsync(context, "insert into foundation_catalog.product_alias (tenant_id,id,variant_id,alias,normalized_alias,alias_type,language_code,created_at) values ($1,$2,$3,$4,$5,$6,$7,$8)", token, tenantId.Value, Guid.CreateVersion7(), request.VariantId, request.Alias.Trim(), CatalogNormalization.Search(request.Alias), request.AliasType, request.LanguageCode ?? (object)DBNull.Value, DateTimeOffset.UtcNow); return true; }, ct); }
    public async Task<bool> AddTranslationAsync(TenantId tenantId, Guid templateId, AddTranslationRequest request, CancellationToken ct) { return await coordinator.ExecuteAsync(tenantId, async (context, token) => { await ExecuteAsync(context, "insert into foundation_catalog.product_translation (tenant_id,id,template_id,language_code,name,description) values ($1,$2,$3,$4,$5,$6)", token, tenantId.Value, Guid.CreateVersion7(), templateId, request.LanguageCode.Trim(), request.Name.Trim(), request.Description ?? (object)DBNull.Value); return true; }, ct); }
    public async Task<ProductReferenceDto> AddReferenceAsync(TenantId tenantId, Guid templateId, AddReferenceRequest request, CancellationToken ct) { var id = Guid.CreateVersion7(); await coordinator.ExecuteAsync(tenantId, async (context, token) => { await EnsureVariantAsync(context, tenantId, templateId, request.VariantId, token); await ExecuteAsync(context, "insert into foundation_catalog.product_reference (tenant_id,id,variant_id,reference_type,party_id,reference_code,status) values ($1,$2,$3,$4,$5,$6,'Active')", token, tenantId.Value, id, request.VariantId, request.ReferenceType, request.PartyId ?? (object)DBNull.Value, request.ReferenceCode.Trim()); return true; }, ct); return new ProductReferenceDto(id, request.VariantId, request.ReferenceType, request.PartyId, request.ReferenceCode.Trim(), CatalogStatus.Active); }

    private static async Task EnsureVariantAsync(ITransactionContext context,TenantId tenantId,Guid templateId,Guid variantId,CancellationToken ct){var found=await ScalarNullableGuidAsync(context,"select product_template_id from foundation_catalog.product_variant where tenant_id=$1 and id=$2",ct,tenantId.Value,variantId);if(found!=templateId)throw new CatalogException("catalog.variant_not_found","Variant was not found for this product.");}
    private static async Task RefreshProjectionAsync(ITransactionContext context,TenantId tenantId,Guid templateId,Guid variantId,CancellationToken ct){await ExecuteAsync(context,"delete from foundation_catalog.catalog_search_projection where tenant_id=$1 and variant_id=$2",ct,tenantId.Value,variantId);await ExecuteAsync(context,"insert into foundation_catalog.catalog_search_projection (tenant_id,variant_id,template_id,display_name,display_name_normalized,name_ar,name_en,sku,normalized_sku,category_id,category_name,base_uom_code,product_nature,status,updated_at) select p.tenant_id,v.id,p.id,p.display_name,p.display_name_normalized,p.name_ar,p.name_en,v.sku,v.normalized_sku,p.category_id,c.name,u.code,p.product_nature,p.status,p.updated_at from foundation_catalog.product_template p join foundation_catalog.product_variant v on v.tenant_id=p.tenant_id and v.product_template_id=p.id left join foundation_catalog.product_category c on c.tenant_id=p.tenant_id and c.id=p.category_id left join foundation_catalog.product_uom pu on pu.tenant_id=v.tenant_id and pu.variant_id=v.id and pu.is_base and pu.status='Active' and pu.effective_to is null left join foundation_catalog.uom u on u.tenant_id=pu.tenant_id and u.id=pu.uom_id where p.tenant_id=$1 and p.id=$2 and v.id=$3",ct,tenantId.Value,templateId,variantId);}
    private static async Task SetTenantAsync(NpgsqlConnection connection,TenantId tenantId,CancellationToken ct){await using var command=new NpgsqlCommand("select set_config('app.tenant_id',$1,false)",connection);command.Parameters.AddWithValue(tenantId.Value.ToString("D"));await command.ExecuteNonQueryAsync(ct);}
    private static async Task<int> ExecuteAsync(ITransactionContext context,string sql,CancellationToken ct,params object[] values){await using var command=new NpgsqlCommand(sql,context.Connection,context.Transaction);for(var i=0;i<values.Length;i++)command.Parameters.AddWithValue(values[i]??DBNull.Value);return await command.ExecuteNonQueryAsync(ct);}
    private static async Task<T> ScalarAsync<T>(ITransactionContext context,string sql,CancellationToken ct,params object[] values){await using var command=new NpgsqlCommand(sql,context.Connection,context.Transaction);for(var i=0;i<values.Length;i++)command.Parameters.AddWithValue(values[i]??DBNull.Value);var value=await command.ExecuteScalarAsync(ct);if(value is null or DBNull)throw new KeyNotFoundException("catalog.not_found");if(value is T result)return result;if(typeof(T)==typeof(Guid))return(T)(object)Guid.Parse(Convert.ToString(value,CultureInfo.InvariantCulture)!);if(typeof(T)==typeof(Guid?))return(T)(object)(Guid?)Guid.Parse(Convert.ToString(value,CultureInfo.InvariantCulture)!);return(T)Convert.ChangeType(value,Nullable.GetUnderlyingType(typeof(T))??typeof(T),CultureInfo.InvariantCulture);}
    private static async Task<Guid?> ScalarNullableGuidAsync(ITransactionContext context,string sql,CancellationToken ct,params object[] values){await using var command=new NpgsqlCommand(sql,context.Connection,context.Transaction);for(var i=0;i<values.Length;i++)command.Parameters.AddWithValue(values[i]??DBNull.Value);var value=await command.ExecuteScalarAsync(ct);return value is null or DBNull?null:(Guid)value;}
}
